# ===== QUERY ENGINE =====
# Element representation for query:
# We'll define classes as dicts with 'kind': 'heading','code','link','table','list','blockquote','image','text','number','bool','dict','array', etc.
# For headings: {'kind':'heading','level':int,'text':str,'line':int (1-indexed actual), 'section': section dict (for content/md), 'heading': heading dict}
# For code: {'kind':'code','language':str,'content':str}
# For link: {'kind':'link','text':str,'url':str,'link_type':str (external/anchor/relative), 'title':...}
# For table: {'kind':'table','headers':[],'rows':[]}
# For list: {'kind':'list','ordered':bool,'items':[{'content':str,'checked':...}]}
# For text/string: {'kind':'string','value':str}
# For number: {'kind':'number','value':float}
# For bool: {'kind':'bool','value':bool}
# For dict (stats etc.): {'kind':'dict','value':dict}
# For array: not element, but list of elements? Actually query results are lists. We'll represent stream as list.

def get_link_type(url):
    if url.startswith('#'):
        return 'anchor'
    if re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', url):
        return 'external'
    return 'relative'

def collect_elements(doc):
    # Returns dict with headings, codes, links, tables, lists, blockquotes, images?
    # Headings: from doc['headings'] (including synthetic? Yes)
    # But need to handle synthetic? For hello file, headings has Input, good.
    # For #no-space file with no headings, headings empty.
    headings = []
    for h in doc['headings']:
        # Find section for this heading? For synthetic, section is doc['sections'][0]
        # For normal, find section with same title/level/line? Use heading dict identity? Our doc['sections'] flat list corresponds to headings in order (except synthetic? Synthetic also has section). So headings and sections correspond 1-1 in order? For non-synthetic, headings[i] corresponds to sections[i] (since sections built from headings in order). Good.
        # Find section index
        sec = None
        for s in doc['sections']:
            if s['heading'] is h:
                sec = s
                break
        headings.append({'kind':'heading','level':h['level'],'text':h['text'],'line':h['line'],'section':sec,'heading':h})
    # Codes, links, tables, lists, blockquotes: from all sections' blocks (direct content only? Or full? For test.md, Section B blocks contain all. Section A blocks contain paragraph only. So collecting from all sections' direct blocks gives all elements. Good.
    # But what about content before first heading (leading text discarded)? That text is not in any section, so its elements would be missed. Original discards leading text, so its elements are also discarded? For 'hello\n\n# Real\n' with leading hello, hello's elements are discarded. That's fine.
    codes = []
    links = []
    tables = []
    lists = []
    blockquotes = []
    images = []  # parsed but query returns empty
    for sec in doc['sections']:
        for b in sec.get('blocks', []):
            if b['type'] == 'code':
                codes.append({'kind':'code','language':b.get('language',''),'content':b.get('content',''),'block':b})
            elif b['type'] == 'paragraph':
                for inl in b.get('inline', []):
                    if inl['type'] == 'link':
                        lt = get_link_type(inl['url'])
                        links.append({'kind':'link','text':inl['text'],'url':inl['url'],'title':inl.get('title'),'link_type':lt,'inline':inl})
                    elif inl['type'] == 'image':
                        images.append({'kind':'image','alt':inl.get('alt',''),'src':inl.get('src',''),'title':inl.get('title')})
            elif b['type'] == 'table':
                tables.append({'kind':'table','headers':b.get('headers',[]),'rows':b.get('rows',[]),'alignments':b.get('alignments',[]),'block':b})
            elif b['type'] == 'list':
                # Each list block is one element? For query, .list returns each list block as one element. Good.
                lists.append({'kind':'list','ordered':b.get('ordered',False),'items':b.get('items',[]),'block':b})
            elif b['type'] == 'blockquote':
                blockquotes.append({'kind':'blockquote','content':b.get('content',''),'block':b})
    # Also need to handle lists/tables etc. in synthetic? Already included.
    return {'headings':headings,'codes':codes,'links':links,'tables':tables,'lists':lists,'blockquotes':blockquotes,'images':images,'doc':doc}

