def parse_query(text):
    # Tokenize with positions
    # First, handle empty? Empty query '' => error Expected expression, found end of input (as observed for -q ''? Actually -q '' with empty expression? We tested -q ''? No, we tested q('')? That was query '' empty string => error Expected expression, found end. Good.
    if text == '':
        raise QueryErrorWithPos("Expected expression, found end of input", 0, "unexpected token")
    toks = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c == '.':
            toks.append(('.', '.', i))
            i += 1
            continue
        if c == ',':
            toks.append((',', ',', i))
            i += 1
            continue
        if c == '|':
            toks.append(('|', '|', i))
            i += 1
            continue
        if c == '>':
            if i+1 < n and text[i+1] == '>':
                toks.append(('>>', '>>', i))
                i += 2
            else:
                toks.append(('>', '>', i))
                i += 1
            continue
        if c in '[](),:':
            toks.append((c, c, i))
            i += 1
            continue
        if c == '"' or c == "'":
            quote = c
            j = i+1
            val = ''
            while j < n and text[j] != quote:
                if text[j] == '\\' and j+1 < n:
                    val += text[j+1]
                    j += 2
                else:
                    val += text[j]
                    j += 1
            if j >= n:
                # Unterminated? Treat as error? Original? Unclear. We'll raise generic.
                raise QueryError(f"Unterminated string")
            toks.append(('STRING', val, i))
            i = j+1
            continue
        if c.isdigit() or (c == '-' and i+1 < n and text[i+1].isdigit()):
            j = i
            if text[j] == '-':
                j += 1
            while j < n and text[j].isdigit():
                j += 1
            if j < n and text[j] == '.' and j+1 < n and text[j+1].isdigit():
                j += 1
                while j < n and text[j].isdigit():
                    j += 1
            toks.append(('NUMBER', text[i:j], i))
            i = j
            continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (text[j].isalnum() or text[j] in '_-'):
                j += 1
            toks.append(('IDENT', text[i:j], i))
            i = j
            continue
        if c == '-':
            toks.append(('-', '-', i))
            i += 1
            continue
        # Unknown char
        raise QueryError(f"Unexpected character '{c}'")
    p = Parser(text, toks)
    node = parse_union(p)
    # After parsing, should be at end; if extra tokens, error? e.g., '.h2 || text' second '|' unexpected? Actually after parsing '.h2 |' then expecting expression, found '|' => error. Our parse_pipe will handle.
    # If leftover tokens (e.g., extra ']'?), treat as error? For simplicity, if pos < len, error unexpected?
    if p.pos < len(toks):
        t = toks[p.pos]
        # e.g., '.h2[0:1:2]' extra ':'? Our filter parsing will handle. For other leftovers, generic?
        raise QueryErrorWithPos(f"Expected expression, found {p.describe_token(t)}", t[2], "unexpected token")
    return node

def parse_union(p):
    # Union := Pipe (',' Pipe)*
    nodes = [parse_pipe(p)]
    while p.peek_type() == ',':
        p.consume()
        # After comma, expect pipe (expression). If end or '|' etc., error expected expression.
        nxt = p.peek()
        if nxt is None or nxt[0] in ('|', ',', ')', ']', '>', '>>', ':'):
            # error expected expression
            if nxt is None:
                raise QueryErrorWithPos("Expected expression, found end of input", len(p.text), "unexpected token")
            else:
                # describe?
                if nxt[0] in ('|', '>', '>>', ',', ')', ']', ':', '.',):
                    desc = f"'{nxt[1]}'"
                else:
                    desc = f"'{nxt[1]}'"
                raise QueryErrorWithPos(f"Expected expression, found {desc}", nxt[2], "unexpected token")
        nodes.append(parse_pipe(p))
    if len(nodes) == 1:
        return nodes[0]
    return ('union', nodes)

def parse_pipe(p):
    # Pipe := Hierarchy ('|' Hierarchy)*
    nodes = [parse_hierarchy(p)]
    while p.peek_type() == '|':
        p.consume()
        nxt = p.peek()
        if nxt is None:
            raise QueryErrorWithPos("Expected expression, found end of input", len(p.text), "unexpected token")
