def cmp(args, stdin=None, env=None):
    import os
    e=os.environ.copy()
    if env: e.update(env)
    p1=subprocess.run(['./executable']+args, input=stdin, capture_output=True, text=True, env=e)
    p2=subprocess.run(['python3','/workspace/treemd_main.py']+args, input=stdin, capture_output=True, text=True, env=e)
    return (p1.stdout==p2.stdout and p1.stderr==p2.stderr and p1.returncode==p2.returncode)

tests=[]
for f in ['/tmp/test.md','README.md','/tmp/lvl.md']:
    for args in [['-l',f],['-l','-o','json',f],['--tree',f],['--count',f]]:
